//! SHX shape fonts of the drawing Font list (live asb 10-24: APMONO, ARComp,
//! ARIsoP1, ARItal, ARMono, ARSimp, ARTxt are single-stroke shape fonts on
//! Onshape's server, proprietary, never sent to clients). Ours are our own:
//! the Hershey fonts' single-stroke glyphs (Roman Simplex, Roman Duplex,
//! Italic; see `hershey/NOTICE.txt` for their use notice and
//! attribution), fitted per character to live's measured advance and ink
//! baseline ([`METRICS`]). No AR* outline is used.

/// The Hershey glyph set a shape font is drawn with (lead decision: Hershey
/// based, fitted to the AR* metrics): simplex for the plain ones, duplex for
/// ARComp (AutoCAD's complex), italic for ARItal.
fn hershey_of(family: &str) -> Option<&'static str> {
    match family {
        "APMONO" | "ARMono" | "ARSimp" | "ARTxt" | "ARIsoP1" => Some(include_str!("hershey/rowmans.jhf")),
        "ARComp" => Some(include_str!("hershey/rowmand.jhf")),
        "ARItal" => Some(include_str!("hershey/timesi.jhf")),
        _ => None,
    }
}

/// A Hershey glyph: its strokes (x right, y up, Hershey units).
struct Glyph {
    strokes: Vec<Vec<[f64; 2]>>,
}

impl Glyph {
    fn ink(&self) -> Option<[f64; 4]> {
        let pts = self.strokes.iter().flatten();
        let mut b = [f64::MAX, f64::MAX, f64::MIN, f64::MIN];
        for p in pts {
            b = [b[0].min(p[0]), b[1].min(p[1]), b[2].max(p[0]), b[3].max(p[1])];
        }
        (b[0] <= b[2]).then_some(b)
    }
}

/// The glyphs of a `.jhf` file: one line per glyph, ASCII 32 on; each a
/// number, a vertex count, the left / right bounds, then coordinate pairs
/// as letters ('R' = 0, y down), " R" lifting the pen.
fn parse(jhf: &str) -> Vec<Glyph> {
    jhf.lines()
        .filter(|l| l.len() >= 10)
        .map(|l| {
            let b = l.as_bytes();
            let coord = |c: u8| (c as f64) - (b'R' as f64);
            let mut strokes: Vec<Vec<[f64; 2]>> = vec![Vec::new()];
            for pair in b[10..].chunks(2).filter(|p| p.len() == 2) {
                if pair == b" R" {
                    strokes.push(Vec::new());
                } else if let Some(s) = strokes.last_mut() {
                    s.push([coord(pair[0]), -coord(pair[1])]);
                }
            }
            strokes.retain(|s| !s.is_empty());
            Glyph { strokes }
        })
        .collect()
}

/// A text in shape font `family`: its strokes and width in text heights
/// (baseline at 0, starting at x 0); None for other families. Characters
/// outside ASCII 32–126 draw as "?".
pub fn shx_text(family: &str, text: &str) -> Option<(Vec<Vec<[f64; 2]>>, f64)> {
    let metrics = &METRICS.iter().find(|(f, _)| *f == family)?.1;
    let glyphs = parse(hershey_of(family)?);
    let index = |c: char| (c as usize).checked_sub(32).filter(|i| *i < 95).unwrap_or('?' as usize - 32);
    // One scale per font: live's "H" ink height over the Hershey "H"'s.
    let h = index('H');
    let hh = glyphs.get(h).and_then(Glyph::ink).map(|b| b[3] - b[1]).unwrap_or(21.0);
    let s = (metrics[h][2] - metrics[h][1]) / hh.max(1e-9);
    let mut out = Vec::new();
    let mut x = 0.0;
    for c in text.chars() {
        let i = index(c);
        let [adv, ymin, _] = metrics[i];
        if let Some(g) = glyphs.get(i)
            && let Some(b) = g.ink()
        {
            // Centred in live's advance, its ink bottom on live's.
            let dx = x + (adv - (b[2] - b[0]) * s) / 2.0 - b[0] * s;
            let dy = if ymin.is_nan() { -b[1] * s } else { ymin - b[1] * s };
            for st in &g.strokes {
                out.push(st.iter().map(|p| [dx + p[0] * s, dy + p[1] * s]).collect());
            }
        }
        x += adv;
    }
    Some((out, x))
}

