#[cfg(test)]
mod tests {
    use super::*;

    /// Our glyphs sit at live's advances: ARSimp "Ai" is 1.0476 + 0.3810
    /// text heights wide; ARMono is monospaced (1.0 each); every family
    /// draws ink; other families have none.
    #[test]
    fn shape_fonts_follow_lives_advances() {
        let (strokes, w) = shx_text("ARSimp", "Ai").unwrap();
        assert!((w - (1.047619 + 0.380952)).abs() < 1e-5 && !strokes.is_empty(), "{w}");
        assert!((shx_text("ARMono", "iWm").unwrap().1 - 3.0).abs() < 1e-6);
        for f in ["APMONO", "ARComp", "ARIsoP1", "ARItal", "ARMono", "ARSimp", "ARTxt"] {
            let (st, w) = shx_text(f, "HAg").unwrap();
            assert!(w > 0.0 && !st.is_empty(), "{f}");
            // The H stands on the baseline, about one text height tall.
            let (hs, _) = shx_text(f, "H").unwrap();
            let ys: Vec<f64> = hs.iter().flatten().map(|p| p[1]).collect();
            let (lo, hi) = ys.iter().fold((f64::MAX, f64::MIN), |(a, b), y| (a.min(*y), b.max(*y)));
            assert!(lo.abs() < 0.1 && (hi - 1.0).abs() < 0.15, "{f} {lo} {hi}");
        }
        assert!(shx_text("Noto Sans", "H").is_none());
    }
}
